<template><div class="map-picker-controls"><details ref="root" class="map-picker" @toggle="toggled"><summary ref="trigger"><span class="map-mini" aria-hidden="true">▦</span><span>맵 <strong>{{ MAP_OPTIONS[selected]?.name }}</strong></span><span class="map-change">직접 선택 ↗</span></summary><div v-show="opened" class="map-backdrop" @click.self="close"><section ref="dialog" role="dialog" aria-modal="true" :aria-labelledby="titleId" class="map-dialog" @keydown.stop="trap"><header><div><span>CHOOSE YOUR PLAYGROUND</span><h2 :id="titleId">오늘은, 어떤 맵?</h2></div><button class="map-close" aria-label="맵 선택 닫기" @click="close">✕</button></header><p>두 플레이어는 같은 지형에서 시작해요. 2인 대전은 매 판 새 맵을 추첨합니다.</p><div class="map-grid"><button v-for="(option,index) in MAP_OPTIONS" :key="index" :data-map="index" :aria-pressed="selected===index" :aria-label="`${option.name} 맵 선택`" @click="choose(index)"><span class="map-preview" :style="{background:`hsl(${95+option.hue} 45% 22%)`}" aria-hidden="true"><i v-for="(cell,n) in preview(index)" :key="n" :style="{background:colors[cell]}"></i></span><span class="map-copy"><strong>{{ option.name }} <b v-if="selected===index">✓</b></strong><small>{{ option.level }}</small><span class="description">{{ option.description }}</span></span></button></div><footer><span>맵은 달라도, 즐거움은 똑같이.</span><button class="random-map" @click="random">✦ 랜덤으로 골라줘</button></footer></section></div></details><button class="quick-random" aria-label="랜덤 맵 고르기" @click="random">🎲 랜덤</button><span class="map-announcement" role="status" aria-live="polite">{{ announcement }}</span></div></template>
<script setup lang="ts">
import {ref,useId,nextTick,onUnmounted} from 'vue'
import {CLASSIC_MAPS,MAP_OPTIONS} from '~/game/ClassicMaps'
const props=defineProps<{selected:number}>(),emit=defineEmits<{select:[index:number]}>()
const root=ref<HTMLDetailsElement|null>(null),trigger=ref<HTMLElement|null>(null),dialog=ref<HTMLElement|null>(null),opened=ref(false),announcement=ref(''),titleId=useId()
defineExpose({open:()=>{if(root.value)root.value.open=true}})
let oldOverflow:string|null=null
const colors=['#ffffff0a','#37ccef','#f4d02b','#bb65ea','#92df36','#ff729b','#659afa','#ffaf5d']
const preview=(index:number)=>(index===0?Array(200).fill(0):CLASSIC_MAPS[index-1]!.flat()) as number[]
async function toggled(){const open=!!root.value?.open;opened.value=open;if(open){oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();dialog.value?.querySelector<HTMLElement>('[aria-pressed=true]')?.focus()}else{restore();trigger.value?.focus()}}
function restore(){if(oldOverflow!==null){document.body.style.overflow=oldOverflow;oldOverflow=null}}
function close(){if(root.value)root.value.open=false;opened.value=false;restore();trigger.value?.focus()}
function choose(index:number){emit('select',index);close()}
function random(){const choices=MAP_OPTIONS.map((_,index)=>index).filter(index=>index!==props.selected);const index=choices[Math.floor(Math.random()*choices.length)]!;announcement.value=`랜덤 맵: ${MAP_OPTIONS[index]!.name}. 두 플레이어에게 같은 맵이 적용돼요.`;choose(index)}
function trap(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close();return}if(event.key!=='Tab')return;const nodes=Array.from(dialog.value?.querySelectorAll<HTMLElement>('button')||[]);const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
onUnmounted(restore)
</script>
<style scoped>
.map-picker-controls{display:flex;align-items:center;gap:12px;min-width:0}.map-picker-controls>.map-picker{flex:1;min-width:0}.quick-random{flex-shrink:0;min-height:39px;padding:8px 14px;border:2px solid #fff;border-radius:12px;background:linear-gradient(#fff2a8,#f4c848);color:#694b13;font:bold 12px -apple-system,Arial;cursor:pointer;box-shadow:0 2px #bd922a}.quick-random:focus-visible{outline:3px solid #9366c8;outline-offset:3px}.map-announcement{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}

.map-picker{color:#43573a;font-family:-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo',sans-serif;margin:15px 0}.map-picker summary{display:flex;align-items:center;gap:9px;cursor:pointer;min-height:39px;list-style:none;font-size:10px;outline-offset:4px}.map-picker summary::-webkit-details-marker{display:none}.map-picker summary strong{font-size:11px;margin-left:7px;font-weight:750;color:#82639b}.map-mini{display:grid;place-items:center;width:28px;height:28px;border-radius:8px;background:#eae4f5;color:#9b81ba;font-size:17px}.map-change{margin-left:auto;color:#7c6293;font-size:9px;padding-left:15px}.map-backdrop{box-sizing:border-box;min-width:0;position:fixed;inset:0;z-index:25000;display:grid;place-items:center;padding:24px;background:#24332455;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}.map-dialog{box-sizing:border-box;width:min(780px,calc(100vw - 48px));min-width:0;max-width:100%;max-height:88dvh;overflow:auto;border:1px solid #fff;border-radius:29px;background:#fafbf5;padding:27px;box-shadow:0 25px 90px #22302033;text-align:left}.map-dialog header{display:flex;justify-content:space-between;gap:20px;align-items:center}.map-dialog header span{font:750 8px ui-monospace,monospace;letter-spacing:1.7px;color:#a0ad8e}.map-dialog h2{font-size:27px;letter-spacing:-1.2px;color:#344b2d;margin:9px 0 0}.map-close{width:37px;height:37px;border:1px solid #e0e5d6;background:white;border-radius:50%;color:#a4ae97;flex-shrink:0;font-size:14px;cursor:pointer}.map-dialog>p{font-size:11px;color:#70825c;margin:14px 0 22px;line-height:1.7}.map-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.map-grid button{display:flex;align-items:center;gap:11px;text-align:left;border:1px solid #e4e8da;background:white;border-radius:17px;color:#405536;padding:12px;cursor:pointer;min-width:0}.map-grid button[aria-pressed=true]{border:2px solid #a987cf;background:#f1eaf9;padding:11px}.map-grid button:hover{border-color:#bda2da;background:#f7f3fb}.map-grid button:focus-visible,.map-dialog button:focus-visible,.map-picker summary:focus-visible{outline:3px solid #9366c8;outline-offset:3px}.map-preview{box-sizing:border-box;flex-shrink:0;width:48px;height:96px;display:grid;grid-template-columns:repeat(10,1fr);grid-template-rows:repeat(20,1fr);gap:.7px;padding:4px;border-radius:7px;border:2px solid #394e32}.map-preview i{display:block}.map-copy{min-width:0}.map-grid strong,.map-grid small,.description{display:block}.map-grid strong{font-size:11px;line-height:1.5;margin:0 0 7px;overflow-wrap:anywhere}.map-grid small{color:#796948;font-size:8px;font-weight:600}.description{font-size:9px;color:#748365;line-height:1.6;margin-top:8px}.map-grid b{color:#a278c5;margin-left:3px}.map-dialog footer{display:flex;align-items:center;justify-content:space-between;gap:15px;border-top:1px solid #e5eada;margin-top:20px;padding-top:18px}.map-dialog footer span{font-size:9px;color:#71865b}.random-map{font:700 11px -apple-system,Arial;color:#6d8a3c;border:1px solid #cbdca7;background:#e8f4d4;border-radius:14px;padding:11px 15px;cursor:pointer}@media(max-width:700px){.map-picker summary{min-height:33px}.map-backdrop{padding:14px}.map-dialog{width:calc(100vw - 28px);padding:21px 17px;border-radius:24px;max-height:90dvh}.map-dialog h2{font-size:23px}.map-dialog header span{font-size:6px;letter-spacing:1.3px}.map-dialog>p{font-size:10px;margin:12px 0 17px}.map-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.map-grid button{gap:8px;padding:9px;border-radius:14px}.map-grid button[aria-pressed=true]{padding:8px}.map-preview{width:39px;height:78px;padding:3px;gap:.5px}.map-grid strong{font-size:10px;margin-bottom:4px}.map-grid small{font-size:7px}.description{font-size:8px;line-height:1.5;margin-top:5px}.map-dialog footer{gap:8px;align-items:stretch;flex-direction:column;margin-top:17px;padding-top:15px}.map-dialog footer span{font-size:8px;text-align:center}.random-map{min-height:42px}.map-copy{min-width:0}}@media(prefers-reduced-transparency:reduce){.map-backdrop{background:#33422cc9;backdrop-filter:none;-webkit-backdrop-filter:none}}
</style>
